        public function __construct(mixed ...$args) {}

        /**
         * Opens a file.
         */
        public function open(string $filename, int $flags, ?string $encoding = null /* String() */): bool {}

        /**
         * Checks whether the file is opened.
         */
        public function isOpened(): bool {}

        /**
         * Closes the file and releases all the memory buffers.
         */
        public function release(): void {}

        /**
         * Closes the file and releases all the memory buffers.
         */
        public function releaseAndGetString(): string {}

        /**
         * Returns the first element of the top-level mapping.
         * @returns The first element of the top-level mapping.
         */
        public function getFirstTopLevelNode(): FileNode {}

        /**
         * Returns the top-level mapping
         * @param streamidx Zero-based index of the stream. In most cases there is only one stream in the file.
         * However, YAML supports multiple streams and so there can be several.
         * @returns The top-level mapping.
         */
        public function root(?int $streamidx = null /* 0 */): FileNode {}

        /**
         * @overload
         */
        public function getNode(string $nodename): FileNode {}

        /**
         * * @brief Simplified writing API to use with bindings.
         * * @param name Name of the written object. When writing to sequences (a.k.a. "arrays"), pass an empty string.
         * * @param val Value of the written object.
         *
         * Overloads, chosen by argument types:
         *   write(string $name, int $val): void
         *   write(string $name, bool $val): void
         *   write(string $name, int $val): void
         *   write(string $name, float $val): void
         *   write(string $name, string $val): void
         *   write(string $name, Mat|array|string $val): void
         *   write(string $name, array $val): void
         */
        public function write(mixed ...$args): mixed {}

        /**
         * Writes a comment.
         */
        public function writeComment(string $comment, ?bool $append = null /* false */): void {}

        /**
         * Starts to write a nested structure (sequence or a mapping).
         * @param name name of the structure. When writing to sequences (a.k.a. "arrays"), pass an empty string.
         * @param flags type of the structure (FileNode::MAP or FileNode::SEQ (both with optional FileNode::FLOW)).
         * @param typeName optional name of the type you store. The effect of setting this depends on the storage format.
         * I.e. if the format has a specification for storing type information, this parameter is used.
         */
        public function startWriteStruct(string $name, int $flags, ?string $typeName = null /* String() */): void {}

        /**
         * Finishes writing nested structure (should pair startWriteStruct())
         */
        public function endWriteStruct(): void {}

        /**
         * Returns the current format.
         * * @returns The current format, see FileStorage::Mode
         */
        public function getFormat(): int {}
    }

