    class Subdiv2D
    {

        /**
         * creates an empty Subdiv2D object.
         * *    To create a new empty Delaunay subdivision you need to use the #initDelaunay function.
         *
         * Overloads, chosen by argument types:
         *   __construct()
         *   __construct(array $rect)
         *   __construct(array $rect2f)
         */
        public function __construct(mixed ...$args) {}

        /**
         * @overload
         * *
         * *    @brief Creates a new empty Delaunay subdivision
         * *
         * *    @param rect Rectangle that includes all of the 2D points that are to be added to the subdivision.
         * *
         */
        public function initDelaunay(array $rect): void {}

        /**
         * @overload
         * *
         * *    @brief Creates a new empty Delaunay subdivision
         * *
         * *    @param rect Rectangle that includes all of the 2d points that are to be added to the subdivision.
         * *
         */
        public function initDelaunay2f(array $rect): void {}

        /**
         * Insert a single point into a Delaunay triangulation.
         * *
         * *    @param pt Point to insert.
         * *
         * *    The function inserts a single point into a subdivision and modifies the subdivision topology
         * *    appropriately. If a point with the same coordinates exists already, no new point is added.
         * *    @returns the ID of the point.
         * *
         * *    @note If the point is outside of the triangulation specified rect a runtime error is raised.
         *
         * Overloads, chosen by argument types:
         *   insert(array $pt): int
         *   insert(array $ptvec): void
         */
        public function insert(mixed ...$args): mixed {}

        /**
         * Returns the location of a point within a Delaunay triangulation.
         * *
         * *    @param pt Point to locate.
         * *    @param edge Output edge that the point belongs to or is located to the right of it.
         * *    @param vertex Optional output vertex the input point coincides with.
         * *
         * *    The function locates the input point within the subdivision and gives one of the triangle edges
         * *    or vertices.
         * *
         * *    @returns an integer which specify one of the following five cases for point location:
         * *    -  The point falls into some facet. The function returns #PTLOC_INSIDE and edge will contain one of
         * *       edges of the facet.
         * *    -  The point falls onto the edge. The function returns #PTLOC_ON_EDGE and edge will contain this edge.
         * *    -  The point coincides with one of the subdivision vertices. The function returns #PTLOC_VERTEX and
         * *       vertex will contain a pointer to the vertex.
         * *    -  The point is outside the subdivision reference rectangle. The function returns #PTLOC_OUTSIDE_RECT
         * *       and no pointers are filled.
         * *    -  One of input arguments is invalid. A runtime error is raised or, if silent or "parent" error
         * *       processing mode is selected, #PTLOC_ERROR is returned.
         *
         * @return array [int, int $edge, int $vertex]
         */
        public function locate(array $pt): array {}

        /**
         * Finds the subdivision vertex closest to the given point.
         * *
         * *    @param pt Input point.
         * *    @param nearestPt Output subdivision vertex point.
         * *
         * *    The function is another function that locates the input point within the subdivision. It finds the
         * *    subdivision vertex that is the closest to the input point. It is not necessarily one of vertices
         * *    of the facet containing the input point, though the facet (located using locate() ) is used as a
         * *    starting point.
         * *
         * *    @returns vertex ID.
         *
         * @return array [int, array $nearestPt]
         */
        public function findNearest(array $pt): array {}

        /**
         * Returns a list of all edges.
         * *
         * *    @param edgeList Output vector.
         * *
         * *    The function gives each edge as a 4 numbers vector, where each two are one of the edge
         * *    vertices. i.e. org_x = v[0], org_y = v[1], dst_x = v[2], dst_y = v[3].
         */
        public function getEdgeList(): array {}

        /**
         * Returns a list of the leading edge ID connected to each triangle.
         * *
         * *    @param leadingEdgeList Output vector.
         * *
         * *    The function gives one edge ID for each triangle.
         */
        public function getLeadingEdgeList(): array {}

        /**
         * Returns a list of all triangles.
         * *
         * *    @param triangleList Output vector.
         * *
         * *    The function gives each triangle as a 6 numbers vector, where each two are one of the triangle
         * *    vertices. i.e. p1_x = v[0], p1_y = v[1], p2_x = v[2], p2_y = v[3], p3_x = v[4], p3_y = v[5].
         */
        public function getTriangleList(): array {}

        /**
         * Returns a list of all Voronoi facets.
         * *
         * *    @param idx Vector of vertices IDs to consider. For all vertices you can pass empty vector.
         * *    @param facetList Output vector of the Voronoi facets.
         * *    @param facetCenters Output vector of the Voronoi facets center points.
         * *
         *
         * @return array [array $facetList, array $facetCenters]
         */
        public function getVoronoiFacetList(array $idx): array {}

        /**
         * Returns vertex location from vertex ID.
         * *
         * *    @param vertex vertex ID.
         * *    @param firstEdge Optional. The first edge ID which is connected to the vertex.
         * *    @returns vertex (x,y)
         * *
         *
         * @return array [array, int $firstEdge]
         */
        public function getVertex(int $vertex): array {}

        /**
         * Returns one of the edges related to the given edge.
         * *
         * *    @param edge Subdivision edge ID.
         * *    @param nextEdgeType Parameter specifying which of the related edges to return.
         * *    The following values are possible:
         * *    -   NEXT_AROUND_ORG next around the edge origin ( eOnext on the picture below if e is the input edge)
         * *    -   NEXT_AROUND_DST next around the edge vertex ( eDnext )
         * *    -   PREV_AROUND_ORG previous around the edge origin (reversed eRnext )
         * *    -   PREV_AROUND_DST previous around the edge destination (reversed eLnext )
         * *    -   NEXT_AROUND_LEFT next around the left facet ( eLnext )
         * *    -   NEXT_AROUND_RIGHT next around the right facet ( eRnext )
         * *    -   PREV_AROUND_LEFT previous around the left facet (reversed eOnext )
         * *    -   PREV_AROUND_RIGHT previous around the right facet (reversed eDnext )
         * *
         * *    ![sample output](pics/quadedge.png)
         * *
         * *    @returns edge ID related to the input edge.
         */
        public function getEdge(int $edge, int $nextEdgeType): int {}

        /**
         * Returns next edge around the edge origin.
         * *
         * *    @param edge Subdivision edge ID.
         * *
         * *    @returns an integer which is next edge ID around the edge origin: eOnext on the
         * *    picture above if e is the input edge).
         */
        public function nextEdge(int $edge): int {}

        /**
         * Returns another edge of the same quad-edge.
         * *
         * *    @param edge Subdivision edge ID.
         * *    @param rotate Parameter specifying which of the edges of the same quad-edge as the input
         * *    one to return. The following values are possible:
         * *    -   0 - the input edge ( e on the picture below if e is the input edge)
         * *    -   1 - the rotated edge ( eRot )
         * *    -   2 - the reversed edge (reversed e (in green))
         * *    -   3 - the reversed rotated edge (reversed eRot (in green))
         * *
         * *    @returns one of the edges ID of the same quad-edge as the input edge.
         */
        public function rotateEdge(int $edge, int $rotate): int {}

        public function symEdge(int $edge): int {}

        /**
         * Returns the edge origin.
         * *
         * *    @param edge Subdivision edge ID.
         * *    @param orgpt Output vertex location.
         * *
         * *    @returns vertex ID.
         *
         * @return array [int, array $orgpt]
         */
        public function edgeOrg(int $edge): array {}

        /**
         * Returns the edge destination.
         * *
         * *    @param edge Subdivision edge ID.
         * *    @param dstpt Output vertex location.
         * *
         * *    @returns vertex ID.
         *
         * @return array [int, array $dstpt]
         */
        public function edgeDst(int $edge): array {}
    }

