     *   getTextSize(array $imgsize, string $text, array $org, FontFace $fface, int $size, ?int $weight = 0, ?int $flags = PUT_TEXT_ALIGN_LEFT, ?array $wrap = Range()): array
     */
    function getTextSize(mixed ...$args): mixed {}

    /**
     * Calculates the font-specific size to use to achieve a given height in pixels.
     */
    function getFontScaleFromHeight(int $fontFace, int $pixelHeight, ?int $thickness = null /* 1 */): float {}

    /**
     * Finds lines in a binary image using the standard Hough transform and get accumulator.
     * *
     * * @note This function is for bindings use only. Use original function in C++ code
     * *
     * * @sa HoughLines
     */
    function HoughLinesWithAccumulator(Mat|array|string $image, float $rho, float $theta, int $threshold, ?float $srn = null /* 0 */, ?float $stn = null /* 0 */, ?float $min_theta = null /* 0 */, ?float $max_theta = null /* CV_PI */, ?bool $use_edgeval = null /* false */): Mat {}

    /**
     * Finds circles in a grayscale image using the Hough transform and get accumulator.
     * *
     * * @note This function is for bindings use only. Use original function in C++ code
     * *
     * * @sa HoughCircles
     */
    function HoughCirclesWithAccumulator(Mat|array|string $image, int $method, float $dp, float $minDist, ?float $param1 = null /* 100 */, ?float $param2 = null /* 100 */, ?int $minRadius = null /* 0 */, ?int $maxRadius = null /* 0 */): Mat {}

    /**
     * Finds the positions of internal corners of the chessboard.
     *
     * @return array [bool, Mat $corners]
     */
    function findChessboardCorners(Mat|array|string $image, array $patternSize, ?int $flags = null /* CALIB_CB_ADAPTIVE_THRESH + CALIB_CB_NORMALIZE_IMAGE */): array {}

    /**
     * Checks whether the image contains chessboard of the specific size or not.
     */
    function checkChessboard(Mat|array|string $img, array $size): bool {}

    /**
     * Finds the positions of internal corners of the chessboard using a sector based approach.
     *
     * @return array [bool, Mat $corners, Mat $meta]
     */
    function findChessboardCornersSBWithMeta(Mat|array|string $image, array $patternSize, int $flags): array {}

    /**
     * @overload
     *
     * @return array [bool, Mat $corners]
     */
    function findChessboardCornersSB(Mat|array|string $image, array $patternSize, ?int $flags = null /* 0 */): array {}

    /**
     * Estimates the sharpness of a detected chessboard.
     *
     * @return array [array, Mat $sharpness]
     */
    function estimateChessboardSharpness(Mat|array|string $image, array $patternSize, Mat|array|string $corners, ?float $rise_distance = null /* 0.8F */, ?bool $vertical = null /* false */): array {}

    function find4QuadCornerSubpix(Mat|array|string $img, Mat $corners, array $region_size): bool {}

    /**
     * Renders the detected chessboard corners.
     */
    function drawChessboardCorners(Mat $image, array $patternSize, Mat|array|string $corners, bool $patternWasFound): void {}
