    /**
     * The main functionality of ArucoDetector class is detection of markers in an image with detectMarkers() method.
     * *
     * * After detecting some markers in the image, you can try to find undetected markers from this dictionary with
     * * refineDetectedMarkers() method.
     * *
     * * @see DetectorParameters, RefineParameters
     */
    class ArucoDetector extends \CV\Algorithm
    {

        /**
         * Basic ArucoDetector constructor
         * *
         * * @param dictionary indicates the type of markers that will be searched
         * * @param detectorParams marker detection parameters
         * * @param refineParams marker refine detection parameters
         *
         * Overloads, chosen by argument types:
         *   __construct(?\CV\aruco\Dictionary $dictionary = getPredefinedDictionary(cv::aruco::DICT_4X4_50), ?\CV\aruco\DetectorParameters $detectorParams = DetectorParameters(), ?\CV\aruco\RefineParameters $refineParams = RefineParameters())
         *   __construct(array $dictionaries, ?\CV\aruco\DetectorParameters $detectorParams = DetectorParameters(), ?\CV\aruco\RefineParameters $refineParams = RefineParameters())
         */
        public function __construct(mixed ...$args) {}

        /**
         * Basic marker detection
         * *
         * * @param image input image
         * * @param corners vector of detected marker corners. For each marker, its four corners
         * * are provided, (e.g std::vector<std::vector<cv::Point2f> > ). For N detected markers,
         * * the dimensions of this array is Nx4. The order of the corners is clockwise.
         * * @param ids vector of identifiers of the detected markers. The identifier is of type int
         * * (e.g. std::vector<int>). For N detected markers, the size of ids is also N.
         * * The identifiers have the same order than the markers in the imgPoints array.
         * * @param rejectedImgPoints contains the imgPoints of those squares whose inner code has not a
         * * correct codification. Useful for debugging purposes.
         * *
         * * Performs marker detection in the input image. Only markers included in the first specified dictionary
         * * are searched. For each detected marker, it returns the 2D position of its corner in the image
         * * and its corresponding identifier.
         * * Note that this function does not perform pose estimation.
         * * @note The function does not correct lens distortion or takes it into account. It's recommended to undistort
         * * input image with corresponding camera model, if camera parameters are known
         * * @sa undistort, estimatePoseSingleMarkers,  estimatePoseBoard
         *
         * @return array [array $corners, Mat $ids, array $rejectedImgPoints]
         */
        public function detectMarkers(Mat|array|string $image): array {}

        /**
         * Marker detection with confidence computation
         * *
         * * @param image input image
         * * @param corners vector of detected marker corners. For each marker, its four corners
         * * are provided, (e.g std::vector<std::vector<cv::Point2f> > ). For N detected markers,
         * * the dimensions of this array is Nx4. The order of the corners is clockwise.
         * * @param ids vector of identifiers of the detected markers. The identifier is of type int
         * * (e.g. std::vector<int>). For N detected markers, the size of ids is also N.
         * * The identifiers have the same order than the markers in the imgPoints array.
         * * @param markersConfidence contains the normalized confidence [0;1] of the markers' detection,
         * * defined as 1 minus the normalized uncertainty (percentage of incorrect pixel detections),
         * * with 1 describing a pixel perfect detection. The confidence values are of type float
         * * (e.g. std::vector<float>)
         * * @param rejectedImgPoints contains the imgPoints of those squares whose inner code has not a
         * * correct codification. Useful for debugging purposes.
         * *
         * * Performs marker detection in the input image. Only markers included in the first specified dictionary
         * * are searched. For each detected marker, it returns the 2D position of its corner in the image
         * * and its corresponding identifier.
         * * Note that this function does not perform pose estimation.
         * * @note The function does not correct lens distortion or takes it into account. It's recommended to undistort
         * * input image with corresponding camera model, if camera parameters are known
         * * @sa undistort, estimatePoseSingleMarkers,  estimatePoseBoard
         *
         * @return array [array $corners, Mat $ids, Mat $markersConfidence, array $rejectedImgPoints]
         */
        public function detectMarkersWithConfidence(Mat|array|string $image): array {}

        /**
         * Refine not detected markers based on the already detected and the board layout
         * *
         * * @param image input image
         * * @param board layout of markers in the board.
         * * @param detectedCorners vector of already detected marker corners.
         * * @param detectedIds vector of already detected marker identifiers.
         * * @param rejectedCorners vector of rejected candidates during the marker detection process.
         * * @param cameraMatrix optional input 3x3 floating-point camera matrix
         * * \f$A = \vecthreethree{f_x}{0}{c_x}{0}{f_y}{c_y}{0}{0}{1}\f$
         * * @param distCoeffs optional vector of distortion coefficients
         * * \f$(k_1, k_2, p_1, p_2[, k_3[, k_4, k_5, k_6],[s_1, s_2, s_3, s_4]])\f$ of 4, 5, 8 or 12 elements
         * * @param recoveredIdxs Optional array to returns the indexes of the recovered candidates in the
         * * original rejectedCorners array.
         * *
         * * This function tries to find markers that were not detected in the basic detecMarkers function.
         * * First, based on the current detected marker and the board layout, the function interpolates
         * * the position of the missing markers. Then it tries to find correspondence between the reprojected
         * * markers and the rejected candidates based on the minRepDistance and errorCorrectionRate parameters.
         * * If camera parameters and distortion coefficients are provided, missing markers are reprojected
         * * using projectPoint function. If not, missing marker projections are interpolated using global
         * * homography, and all the marker corners in the board must have the same Z coordinate.
         * * @note This function assumes that the board only contains markers from one dictionary, so only the
         * * first configured dictionary is used. It has to match the dictionary of the board to work properly.
         *
         * @return array [array $detectedCorners, array $rejectedCorners, Mat $recoveredIdxs]
         */
        public function refineDetectedMarkers(Mat|array|string $image, \CV\aruco\Board $board, array $detectedCorners, Mat $detectedIds, array $rejectedCorners, Mat|array|string|null $cameraMatrix = null /* Mat() */, Mat|array|string|null $distCoeffs = null /* Mat() */): array {}

        /**
         * Basic marker detection
         * *
         * * @param image input image
         * * @param corners vector of detected marker corners. For each marker, its four corners
         * * are provided, (e.g std::vector<std::vector<cv::Point2f> > ). For N detected markers,
         * * the dimensions of this array is Nx4. The order of the corners is clockwise.
         * * @param ids vector of identifiers of the detected markers. The identifier is of type int
         * * (e.g. std::vector<int>). For N detected markers, the size of ids is also N.
         * * The identifiers have the same order than the markers in the imgPoints array.
         * * @param rejectedImgPoints contains the imgPoints of those squares whose inner code has not a
         * * correct codification. Useful for debugging purposes.
         * * @param dictIndices vector of dictionary indices for each detected marker. Use getDictionaries() to get the
         * * list of corresponding dictionaries.
         * *
         * * Performs marker detection in the input image. Only markers included in the specific dictionaries
         * * are searched. For each detected marker, it returns the 2D position of its corner in the image
         * * and its corresponding identifier.
         * * Note that this function does not perform pose estimation.
         * * @note The function does not correct lens distortion or takes it into account. It's recommended to undistort
         * * input image with corresponding camera model, if camera parameters are known
         * * @sa undistort, estimatePoseSingleMarkers,  estimatePoseBoard
         *
