        /**
         * simplified API for language bindings
         */
        public function write(FileStorage $fs, string $name): void {}

        /**
         * Reads algorithm parameters from a file storage
         */
        public function read(FileNode $fn): void {}
    }

    /**
     * Dictionary is a set of unique ArUco markers of the same size
     * *
     * * `bytesList` storing as 2-dimensions Mat with 4-th channels (CV_8UC4 type was used) and contains the marker codewords where:
     * * - bytesList.rows is the dictionary size
     * * - each marker is encoded using `nbytes = ceil(markerSize*markerSize/8.)` bytes
     * * - each row contains all 4 rotations of the marker, so its length is `4*nbytes`
     * * - the byte order in the bytesList[i] row:
     * * `//bytes without rotation/bytes with rotation 1/bytes with rotation 2/bytes with rotation 3//`
     * * So `bytesList.ptr(i)[k*nbytes + j]` is the j-th byte of i-th marker, in its k-th rotation.
     * * @note Python bindings generate matrix with shape of bytesList `dictionary_size x nbytes x 4`,
     * * but it should be indexed like C++ version. Python example for j-th byte of i-th marker, in its k-th rotation:
     * * `aruco_dict.bytesList[id].ravel()[k*nbytes + j]`
     */
    class Dictionary
    {
        public Mat|array|string $bytesList;
        public int $markerSize;
        public int $maxCorrectionBits;

        /**
         *
         * Overloads, chosen by argument types:
         *   __construct()
         *   __construct(Mat|array|string $bytesList, int $_markerSize, ?int $maxcorr = 0)
         */
        public function __construct(mixed ...$args) {}

        /**
         * Read a new dictionary from FileNode.
         * *
         * * Dictionary example in YAML format:\n
         * * nmarkers: 35\n
         * * markersize: 6\n
         * * maxCorrectionBits: 5\n
         * * marker_0: "101011111011111001001001101100000000"\n
         * * ...\n
         * * marker_34: "011111010000111011111110110101100101"
         */
        public function readDictionary(FileNode $fn): bool {}

        /**
         * Write a dictionary to FileStorage, format is the same as in readDictionary().
         */
        public function writeDictionary(FileStorage $fs, ?string $name = null /* String() */): void {}

        /**
         * Given a matrix of bits. Returns whether if marker is identified or not.
         * *
         * * Returns reference to the marker id in the dictionary (if any) and its rotation.
         *
         * Overloads, chosen by argument types:
         *   identify(Mat|array|string $onlyBits, float $maxCorrectionRate): [bool, int $idx, int $rotation]
         *   identify(Mat|array|string $onlyCellPixelRatio, float $maxCorrectionRate, float $validBitIdThreshold): [bool, int $idx, int $rotation]
         */
        public function identify(mixed ...$args): mixed {}

        /**
         * Returns Hamming distance of the input bits to the specific id.
         * *
         * * If `allRotations` flag is set, the four possible marker rotations are considered
         *
         * Overloads, chosen by argument types:
         *   getDistanceToId(Mat|array|string $bits, int $id, ?bool $allRotations = true): int
         *   getDistanceToId(Mat|array|string $onlyCellPixelRatio, int $id, bool $allRotations, float $validBitIdThreshold): int
         */
        public function getDistanceToId(mixed ...$args): mixed {}

        /**
         * Generate a canonical marker image
         */
        public function generateImageMarker(int $id, int $sidePixels, ?int $borderBits = null /* 1 */): Mat {}

        /**
         * Transform matrix of bits to list of bytes with 4 marker rotations
         */
        public static function getByteListFromBits(Mat|array|string $bits): Mat {}

        /**
         * Transform list of bytes to matrix of bits
         */
        public static function getBitsFromByteList(Mat|array|string $byteList, int $markerSize, ?int $rotationId = null /* 0 */): Mat {}

        /**
         * Get ground truth bits float
         */
        public function getMarkerBits(int $markerId, ?int $rotationId = null /* 0 */): Mat {}
    }

