    class CharucoDetector extends \CV\Algorithm
    {

        /**
         * Basic CharucoDetector constructor
         * *
         * * @param board ChAruco board
         * * @param charucoParams charuco detection parameters
         * * @param detectorParams marker detection parameters
         * * @param refineParams marker refine detection parameters
         */
        public function __construct(\CV\aruco\CharucoBoard $board, ?\CV\aruco\CharucoParameters $charucoParams = null /* CharucoParameters() */, ?\CV\aruco\DetectorParameters $detectorParams = null /* DetectorParameters() */, ?\CV\aruco\RefineParameters $refineParams = null /* RefineParameters() */) {}

        public function getBoard(): \CV\aruco\CharucoBoard {}

        public function setBoard(\CV\aruco\CharucoBoard $board): void {}

        public function getCharucoParameters(): \CV\aruco\CharucoParameters {}

        public function setCharucoParameters(\CV\aruco\CharucoParameters $charucoParameters): void {}

        public function getDetectorParameters(): \CV\aruco\DetectorParameters {}

        public function setDetectorParameters(\CV\aruco\DetectorParameters $detectorParameters): void {}

        public function getRefineParameters(): \CV\aruco\RefineParameters {}

        public function setRefineParameters(\CV\aruco\RefineParameters $refineParameters): void {}

        /**
         * * @brief detect aruco markers and interpolate position of ChArUco board corners
         * * @param image input image necessary for corner refinement. Note that markers are not detected and
         * * should be sent in corners and ids parameters.
         * * @param charucoCorners interpolated chessboard corners.
         * * @param charucoIds interpolated chessboard corners identifiers.
         * * @param markerCorners vector of already detected markers corners. For each marker, its four
         * * corners are provided, (e.g std::vector<std::vector<cv::Point2f> > ). For N detected markers, the
         * * dimensions of this array should be Nx4. The order of the corners should be clockwise.
         * * If markerCorners and markerCorners are empty, the function detect aruco markers and ids.
         * * @param markerIds list of identifiers for each marker in corners.
         * *  If markerCorners and markerCorners are empty, the function detect aruco markers and ids.
         * *
         * * This function receives the detected markers and returns the 2D position of the chessboard corners
         * * from a ChArUco board using the detected Aruco markers.
         * *
         * * If markerCorners and markerCorners are empty, the detectMarkers() will run and detect aruco markers and ids.
         * *
         * * If camera parameters are provided, the process is based in an approximated pose estimation, else it is based on local homography.
         * * Only visible corners are returned. For each corner, its corresponding identifier is also returned in charucoIds.
         * * @sa findChessboardCorners
         * * @note In OpenCV 4.6.0 there was an incompatible change in the ChArUco pattern generation algorithm for even row counts.
         * * Use cv::aruco::CharucoBoard::setLegacyPattern() to ensure compatibility with patterns created using OpenCV versions
         * * older than 4.6.0, or with third-party generators such as calib.io that follow the same convention. Boards with an odd
         * * number of rows are unaffected. A mismatch is silent: the markers are still detected, but this function returns zero
         * * ChArUco corners and logs only a CV_LOG_DEBUG message.
         * * For more information, see the issue: https://github.com/opencv/opencv/issues/23152
         *
         * @return array [Mat $charucoCorners, Mat $charucoIds, array $markerCorners]
         */
        public function detectBoard(Mat|array|string $image, ?array $markerCorners = null /* std::vector<cv::Mat>() */, ?Mat $markerIds = null /* Mat() */): array {}

        /**
         * * @brief Detect ChArUco Diamond markers
         * *
         * * @param image input image necessary for corner subpixel.
         * * @param diamondCorners output list of detected diamond corners (4 corners per diamond). The order
         * * is the same than in marker corners: top left, top right, bottom right and bottom left. Similar
         * * format than the corners returned by detectMarkers (e.g std::vector<std::vector<cv::Point2f> > ).
         * * @param diamondIds ids of the diamonds in diamondCorners. The id of each diamond is in fact of
         * * type Vec4i, so each diamond has 4 ids, which are the ids of the aruco markers composing the
         * * diamond.
         * * @param markerCorners list of detected marker corners from detectMarkers function.
         * * If markerCorners and markerCorners are empty, the function detect aruco markers and ids.
         * * @param markerIds list of marker ids in markerCorners.
         * * If markerCorners and markerCorners are empty, the function detect aruco markers and ids.
         * *
         * * This function detects Diamond markers from the previous detected ArUco markers. The diamonds
         * * are returned in the diamondCorners and diamondIds parameters. If camera calibration parameters
         * * are provided, the diamond search is based on reprojection. If not, diamond search is based on
         * * homography. Homography is faster than reprojection, but less accurate.
         *
         * @return array [array $diamondCorners, Mat $diamondIds, array $markerCorners]
         */
        public function detectDiamonds(Mat|array|string $image, ?array $markerCorners = null /* std::vector<cv::Mat>() */, ?Mat $markerIds = null /* Mat() */): array {}
    }

    /**
     * Draw detected markers in image
     * *
     * * @param image input/output image. It must have 1 or 3 channels. The number of channels is not altered.
     * * @param corners positions of marker corners on input image.
     * * (e.g std::vector<std::vector<cv::Point2f> > ). For N detected markers, the dimensions of
     * * this array should be Nx4. The order of the corners should be clockwise.
     * * @param ids vector of identifiers for markers in markersCorners .
     * * Optional, if not provided, ids are not painted.
     * * @param borderColor color of marker borders. Rest of colors (text color and first corner color)
     * * are calculated based on this one to improve visualization.
     * *
     * * Given an array of detected marker corners and its corresponding ids, this functions draws
     * * the markers in the image. The marker borders are painted and the markers identifiers if provided.
     * * Useful for debugging purposes.
     */
    function drawDetectedMarkers(Mat $image, array $corners, Mat|array|string|null $ids = null /* Mat() */, array|int|float|null $borderColor = null /* Scalar(0, 255, 0) */): void {}

    /**
     * Generate a canonical marker image
     * *
     * * @param dictionary dictionary of markers indicating the type of markers
     * * @param id identifier of the marker that will be returned. It has to be a valid id in the specified dictionary.
     * * @param sidePixels size of the image in pixels
     * * @param img output image with the marker
     * * @param borderBits width of the marker border.
     * *
     * * This function returns a marker image in its canonical form (i.e. ready to be printed)
     */
    function generateImageMarker(\CV\aruco\Dictionary $dictionary, int $id, int $sidePixels, ?int $borderBits = null /* 1 */): Mat {}

    /**
     * Returns one of the predefined dictionaries referenced by DICT_*.
     */
    function getPredefinedDictionary(int $dict): \CV\aruco\Dictionary {}

    /**
     * Extend base dictionary by new nMarkers
     * *
     * * @param nMarkers number of markers in the dictionary
     * * @param markerSize number of bits per dimension of each markers
     * * @param baseDictionary Include the markers in this dictionary at the beginning (optional)
     * * @param randomSeed a user supplied seed for theRNG()
     * *
     * * This function creates a new dictionary composed by nMarkers markers and each markers composed
     * * by markerSize x markerSize bits. If baseDictionary is provided, its markers are directly
     * * included and the rest are generated based on them. If the size of baseDictionary is higher
     * * than nMarkers, only the first nMarkers in baseDictionary are taken and no new marker is added.
     */
    function extendDictionary(int $nMarkers, int $markerSize, ?\CV\aruco\Dictionary $baseDictionary = null /* Dictionary() */, ?int $randomSeed = null /* 0 */): \CV\aruco\Dictionary {}

    /**
     * * @brief Draws a set of Charuco corners
     * * @param image input/output image. It must have 1 or 3 channels. The number of channels is not
     * * altered.
     * * @param charucoCorners vector of detected charuco corners
     * * @param charucoIds list of identifiers for each corner in charucoCorners
     * * @param cornerColor color of the square surrounding each corner
     * *
     * * This function draws a set of detected Charuco corners. If identifiers vector is provided, it also
     * * draws the id of each corner.
     */
    function drawDetectedCornersCharuco(Mat $image, Mat|array|string $charucoCorners, Mat|array|string|null $charucoIds = null /* Mat() */, array|int|float|null $cornerColor = null /* Scalar(255, 0, 0) */): void {}

    /**
     * * @brief Draw a set of detected ChArUco Diamond markers
     * *
     * * @param image input/output image. It must have 1 or 3 channels. The number of channels is not
     * * altered.
     * * @param diamondCorners positions of diamond corners in the same format returned by
     * * detectCharucoDiamond(). (e.g std::vector<std::vector<cv::Point2f> > ). For N detected markers,
     * * the dimensions of this array should be Nx4. The order of the corners should be clockwise.
     * * @param diamondIds vector of identifiers for diamonds in diamondCorners, in the same format
     * * returned by detectCharucoDiamond() (e.g. std::vector<Vec4i>).
     * * Optional, if not provided, ids are not painted.
     * * @param borderColor color of marker borders. Rest of colors (text color and first corner color)
     * * are calculated based on this one.
     * *
     * * Given an array of detected diamonds, this functions draws them in the image. The marker borders
     * * are painted and the markers identifiers if provided.
     * * Useful for debugging purposes.
     */
    function drawDetectedDiamonds(Mat $image, array $diamondCorners, Mat|array|string|null $diamondIds = null /* Mat() */, array|int|float|null $borderColor = null /* Scalar(0, 0, 255) */): void {}
}

